//! `managed.lock.json`: what the GitHub release API reported for every asset
//! the manifest names, generated by `dev.mjs lsp:lock` and embedded at build
//! time. Never edited by hand.
use std::collections::BTreeMap;
use std::sync::OnceLock;

const EMBEDDED: &str = include_str!("../managed.lock.json");

/// One asset as GitHub reported it when the lock was generated.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetLock {
    /// The asset's `browser_download_url`.
    pub url: String,
    /// GitHub's upload-time `digest`, lowercase hex without the `sha256:` prefix.
    pub sha256: String,
    pub size: u64,
}

/// The release-level facts the lock records.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ReleaseLock {
    /// GitHub's immutable-release flag: when set, the install also verifies
    /// the release attestation.
    pub immutable: bool,
    pub published_at: String,
}

#[derive(Debug, Default)]
pub(super) struct LockedRelease {
    repo: String,
    tag: String,
    pub(super) summary: ReleaseLock,
    assets: BTreeMap<String, AssetLock>,
}

impl LockedRelease {
    pub(super) fn asset(&self, name: &str) -> Option<&AssetLock> {
        self.assets.get(name)
    }
}

/// The parsed lock, by server name.
#[derive(Debug, Default)]
pub(super) struct Lock {
    servers: BTreeMap<String, LockedRelease>,
}

impl Lock {
    /// The locked release for `server`, only when it records the same
    /// repository and tag the manifest declares now.
    pub(super) fn release(&self, server: &str, repo: &str, tag: &str) -> Option<&LockedRelease> {
        self.servers
            .get(server)
            .filter(|release| release.repo == repo && release.tag == tag)
    }

    /// Parse lock text. Malformed text is a build defect the lock tests catch;
    /// an entry that does not parse is left out, so its install is refused.
    pub(super) fn parse(text: &str) -> Self {
        let Ok(value) = serde_json::from_str::<serde_json::Value>(text) else {
            return Self::default();
        };
        let servers = value
            .get("servers")
            .and_then(serde_json::Value::as_object)
            .into_iter()
            .flatten()
            .filter_map(|(name, release)| Some((name.clone(), parse_release(release)?)))
            .collect();
        Self { servers }
    }
}

fn parse_release(release: &serde_json::Value) -> Option<LockedRelease> {
    let text = |key: &str| release.get(key)?.as_str().map(str::to_owned);
    let assets = release
        .get("assets")?
        .as_object()?
        .iter()
        .filter_map(|(name, asset)| {
            let sha256 = asset.get("sha256")?.as_str()?;
            let valid = sha256.len() == 64
                && sha256
                    .bytes()
                    .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
            let locked = AssetLock {
                url: asset.get("url")?.as_str()?.to_owned(),
                sha256: sha256.to_owned(),
                size: asset.get("size")?.as_u64()?,
            };
            valid.then(|| (name.clone(), locked))
        })
        .collect();
    Some(LockedRelease {
        repo: text("repo")?,
        tag: text("tag")?,
        summary: ReleaseLock {
            immutable: release.get("immutable")?.as_bool()?,
            published_at: text("publishedAt").unwrap_or_default(),
        },
        assets,
    })
}

/// The lock embedded in this binary.
pub(super) fn embedded() -> &'static Lock {
    static LOCK: OnceLock<Lock> = OnceLock::new();
    LOCK.get_or_init(|| Lock::parse(EMBEDDED))
}

#[cfg(test)]
pub(super) fn embedded_text() -> &'static str {
    EMBEDDED
}
